public class Main {
    public static void main(String[] args) {
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);

        int total = 0;
        Node current = head;
        while (current != null) {
            total += current.value;
            current = current.next;
        }
        System.out.println("Total: " + total);
    }
}

class Node {
    int value;
    Node next;

    Node(int value) {
        this.value = value;
    }
}
